"""Rebuild ../index.html from the source files in this folder.
Run:  python3 build.py
"""
import json, os
here = os.path.dirname(os.path.abspath(__file__))
rd = lambda f: open(os.path.join(here, f), encoding="utf-8").read()
J = lambda t: json.dumps(t, ensure_ascii=False)
s = rd("page.src.html")
s = (s.replace("/*@TOPICS@*/", rd("topics.js"))
      .replace("/*@EXTRA@*/", J(rd("extra.txt")))
      .replace("/*@A1@*/", J(rd("a1.txt").strip()))
      .replace("/*@DE@*/", J(rd("de.txt")))
      .replace("/*@PT@*/", J(rd("pt.txt"))))
assert "/*@" not in s, "a placeholder was not filled"
head = """<!doctype html>
<html lang="zh-Hans">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"%3E%3Ccircle cx="50" cy="38" r="30" fill="%23E6EFEA" stroke="%231E2638" stroke-width="4"%3E%3C/circle%3E%3Cg transform="rotate%28-20 39 48%29"%3E%3Cpath d="M30 48 A9 9 0 0 1 48 48 Z" fill="%23E0654A"%3E%3C/path%3E%3Cpath d="M30 48 A9 9 0 0 0 48 48 Z" fill="%23FFFDF6"%3E%3C/path%3E%3Ccircle cx="39" cy="48" r="9" fill="none" stroke="%231E2638" stroke-width="2.6"%3E%3C/circle%3E%3Cline x1="30" y1="48" x2="48" y2="48" stroke="%231E2638" stroke-width="2.6"%3E%3C/line%3E%3C/g%3E%3Cg transform="rotate%2815 59 47%29"%3E%3Cpath d="M50 47 A9 9 0 0 1 68 47 Z" fill="%232C8C88"%3E%3C/path%3E%3Cpath d="M50 47 A9 9 0 0 0 68 47 Z" fill="%23FFFDF6"%3E%3C/path%3E%3Ccircle cx="59" cy="47" r="9" fill="none" stroke="%231E2638" stroke-width="2.6"%3E%3C/circle%3E%3Cline x1="50" y1="47" x2="68" y2="47" stroke="%231E2638" stroke-width="2.6"%3E%3C/line%3E%3C/g%3E%3Cg transform="rotate%285 49 29%29"%3E%3Cpath d="M40 29 A9 9 0 0 1 58 29 Z" fill="%23E2A93B"%3E%3C/path%3E%3Cpath d="M40 29 A9 9 0 0 0 58 29 Z" fill="%23FFFDF6"%3E%3C/path%3E%3Ccircle cx="49" cy="29" r="9" fill="none" stroke="%231E2638" stroke-width="2.6"%3E%3C/circle%3E%3Cline x1="40" y1="29" x2="58" y2="29" stroke="%231E2638" stroke-width="2.6"%3E%3C/line%3E%3C/g%3E%3Cpath d="M30 26 A22 22 0 0 1 42 16" fill="none" stroke="%23FFFFFF" stroke-width="4" stroke-linecap="round" opacity="0.8"%3E%3C/path%3E%3Crect x="24" y="66" width="52" height="28" rx="7" fill="%23B23A2B" stroke="%231E2638" stroke-width="4"%3E%3C/rect%3E%3Ccircle cx="50" cy="80" r="7" fill="%23FFFDF6" stroke="%231E2638" stroke-width="3"%3E%3C/circle%3E%3Cline x1="50" y1="74.5" x2="50" y2="85.5" stroke="%231E2638" stroke-width="3" stroke-linecap="round"%3E%3C/line%3E%3C/svg%3E">
<link rel="apple-touch-icon" href="data:image/png;base64,">
<meta name="theme-color" media="(prefers-color-scheme: light)" content="#F2F2F7">
<meta name="theme-color" media="(prefers-color-scheme: dark)" content="#000000">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="default">
<meta name="apple-mobile-web-app-title" content="话题扭蛋">
<link rel="manifest" href="manifest.webmanifest">
<meta name="description" content="话题扭蛋 · 多语派对聊天话题 / Topic Capsules – party conversation topics in Chinese, English, German and Portuguese">
<style>:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0;-webkit-text-size-adjust:100%}img{max-width:100%}[hidden]{display:none!important}</style>
"""
i = s.index('<div class="shell" id="app">')
out = head + s[:i] + "</head>\n<body>\n" + s[i:] + "\n</body>\n</html>\n"
open(os.path.join(here, "..", "index.html"), "w", encoding="utf-8").write(out)
print("index.html rebuilt,", len(out), "characters")
